"use strict";(self.webpackChunksite=self.webpackChunksite||[]).push([["6592"],{38397(n,e,a){a.r(e),a.d(e,{metadata:()=>t,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"radiopi","title":"RadioPi","description":"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026","source":"@site/docs/radiopi.md","sourceDirName":".","slug":"/radiopi","permalink":"/doc-dev/radiopi","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"RadioPi","description":"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026"},"sidebar":"docs","previous":{"title":"Geekradio","permalink":"/doc-dev/geekradio"},"next":{"title":"Frequence3","permalink":"/doc-dev/frequence3"}}'),i=a(74848),o=a(28453);let s={title:"RadioPi",description:"RadioPi is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels. There are topical channels (Reggae, Hip-Hop, Jazz, ...). On\u2026"},r,l={},d=[{value:"The migration process",id:"the-migration-process",level:3}];function u(n){let e={a:"a",code:"code",h3:"h3",p:"p",pre:"pre",...(0,o.R)(),...n.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(e.p,{children:[(0,i.jsx)(e.a,{href:"http://www.radiopi.org",children:"RadioPi"})," is the web radio of the ECP (Ecole Centrale de Paris). RadioPi runs many channels.\nThere are topical channels (Reggae, Hip-Hop, Jazz, ...). On top of that, they periodically broadcast live shows,\nwhich are relayed on all channels."]}),"\n",(0,i.jsx)(e.p,{children:"We met a RadioPi manager right after having released Liquidsoap 0.2.0, and he was seduced by the system. They needed\nquite complex features, which they were at that time fulfilling using dirty tricks, loads of obfuscated scripts.\nUsing Liquidsoap now allow them to do all they want in an integrated way, but also provided new features."}),"\n",(0,i.jsx)(e.h3,{id:"the-migration-process",children:"The migration process"}),"\n",(0,i.jsx)(e.p,{children:"Quite easy actually. They used to have many instances Ices2, each of these calling a Perl script to get the next song.\nOther scripts were used for switching channels to live shows."}),"\n",(0,i.jsx)(e.p,{children:"Now they have this single Liquidsoap script, no more. It calls external scripts to interact with their web-based song\nscheduling system. And they won new features: blank detection and distributed encoding."}),"\n",(0,i.jsx)(e.p,{children:"The first machine gets its files from a ftp server opened on the second machine.\nLiquidsoap handles download automatically."}),"\n",(0,i.jsxs)(e.p,{children:["Each file is given by an external script, ",(0,i.jsx)(e.code,{children:"radiopilote-getnext"}),",\nwhose answer looks as follows (except that it's on a single line):"]}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{children:'annotate:file_id="3541",length="400.613877551",\\\n type="chansons",title="John Holt - Holigan",\\\n artist="RadioPi - Canal reggae",\\\n album="Studio One SeleKta! - Album Studio 1 12",\\\n canal="reggae":ftp://***:***@host/files/3541.mp3\n'})}),"\n",(0,i.jsx)(e.p,{children:"Note that we use annotate to pass some variables to liquidsoap..."}),"\n",(0,i.jsx)(e.pre,{children:(0,i.jsx)(e.code,{className:"language-liquidsoap",metastring:'title="radiopi.liq"',children:'#!/usr/bin/liquidsoap\n\n# Standard settings\nlog.file := true\nlog.file.path := "/var/log/liquidsoap/pi.log"\nlog.stdout := false\n\n# Enable telnet server\nsettings.server.telnet.set(true)\n\n# Enable harbor for any external connection\nsettings.harbor.bind_addrs.set(["0.0.0.0"])\n\n# Verbose logs\nlog.level.set(4)\n\n# === Settings ===\n\n# The host to request files\nstream = "XXXxXXXx"\n\n# The command to request files\nscripts =\n "ssh XXxxxXXX@#{stream} \'/path/to/scripts/"\n\n# A substitution on the returned path\nsed =\n " | sed -e s#/path/to/files/#ftp://user:password@#{stream}/#\'"\n\n# Enable replay gain\nenable_replaygain_metadata()\n\npass = "XXxXXXXx"\nice_host = "localhost"\n\ndescr = "RadioPi"\nurl = "http://radiopi.org"\n\n# === Live ===\n\n# A live source, on which we strip blank (make the source unavailable when\n# streaming blank).\nlive =\n blank.strip(\n input.harbor(\n id="live",\n port=8000,\n password=pass,\n buffer=8.,\n max=20.,\n "live.ogg"\n ),\n max_blank=10.,\n threshold=-50.\n )\n\n# This source relays the live data, when available, to the other streamer, in\n# uncompressed format (WAV).\noutput.icecast(\n %wav,\n host=stream,\n port=8005,\n password=pass,\n mount="live.ogg",\n fallible=true,\n live\n)\n\n# This source relays the live source to "live.ogg". This is used for debugging\n# purposes, to see what is sent to the harbor source.\noutput.icecast(\n %vorbis,\n host="127.0.0.1",\n port=8080,\n password=pass,\n mount="live.ogg",\n fallible=true,\n live\n)\n\n# This source starts an archive of the live stream when available\ntitle =\n \'$(if $(title),"$(title)","Emission inconnue")$(if $(artist), " par \\\n $(artist)") - %m-%d-%Y, %H:%M:%S\'\noutput.file(\n %vorbis,\n reopen_on_metadata=fun (_) -> true,\n fallible=true,\n "/data/archives/brutes/" ^ title ^ ".ogg",\n live\n)\n\n# === Channels ===\n\n# Specialize the output functions\ndef out(fmt, ~id, ~mount, ~name, ~genre, s) =\n output.icecast(\n fmt,\n id=id,\n description=descr,\n url=url,\n host=ice_host,\n port=8080,\n password=pass,\n fallible=true,\n mount=mount,\n name=name,\n genre=genre,\n s\n )\nend\ndef out_aac32(~id, ~mount, ~name, ~genre, s) =\n out(%fdkaac(bitrate = 32), id=id, mount=mount, name=name, genre=genre, s)\nend\ndef out_aac(~id, ~mount, ~name, ~genre, s) =\n out(%fdkaac(bitrate = 64), id=id, mount=mount, name=name, genre=genre, s)\nend\ndef out(~id, ~mount, ~name, ~genre, s) =\n out(%mp3, id=id, mount=mount, name=name, genre=genre, s)\nend\n\n# A file for playing during failures\ninterlude = single("/home/radiopi/fallback.mp3")\n\n# Lastfm submission\ndef lastfm(m) =\n if\n m["type"] == "chansons"\n and (\n m["canal"] == "reggae"\n or m["canal"] == "Jazz"\n or m["canal"] == "That70Sound"\n )\n then\n canal = if (m["canal"] == "That70Sound") then "70sound" else m["canal"] end\n username = "radiopi-" ^ canal\n audioscrobbler.api.track.scrobble.metadata(\n username=username,\n password="xXXxx",\n m\n )\n end\nend\n\n# === Basic sources ===\n\n# Custom crossfade to deal with jingles.\ndef crossfade(\n ~start_next=5.,\n ~fade_in=3.,\n ~fade_out=3.,\n ~default=(fun (a, b) -> sequence([a, b])),\n ~high=-15.,\n ~medium=-32.,\n ~margin=4.,\n ~width=2.,\n s\n) =\n fade_out = fun (s) -> fade.out(type="sin", duration=fade_out, s)\n fade_in = fun (s) -> fade.in(type="sin", duration=fade_in, s)\n add = fun (a, b) -> add(normalize=false, [b, a])\n log = fun (~level=3, x) -> log(label="crossfade", level=level, x)\n\n def transition(a, b) =\n list.iter(\n fun (x) ->\n log(\n level=4,\n "Before: #{x}"\n ),\n a.metadata\n )\n list.iter(\n fun (x) ->\n log(\n level=4,\n "After : #{x}"\n ),\n b.metadata\n )\n\n if\n a.metadata["type"] == "jingles" or b.metadata["type"] == "jingles"\n then\n log(\n "Old or new file is a jingle: sequenced transition."\n )\n sequence([a.source, b.source])\n elsif\n # If A and B are not too loud and close, fully cross-fade them.\n a.db_level <= medium\n and b.db_level <= medium\n and abs(a.db_level - b.db_level) <= margin\n then\n log(\n "Old <= medium, new <= medium and |old-new| <= margin."\n )\n log(\n "Old and new source are not too loud and close."\n )\n log(\n "Transition: crossed, fade-in, fade-out."\n )\n add(fade_out(a.source), fade_in(b.source))\n elsif\n # If B is significantly louder than A, only fade-out A.\n # We don\'t want to fade almost silent things, ask for >medium.\n b.db_level >= a.db_level + margin\n and a.db_level >= medium\n and b.db_level <= high\n then\n log(\n "new >= old + margin, old >= medium and new <= high."\n )\n log(\n "New source is significantly louder than old one."\n )\n log(\n "Transition: crossed, fade-out."\n )\n add(fade_out(a.source), b.source)\n elsif\n # Opposite as the previous one.\n a.db_level >= b.db_level + margin\n and b.db_level >= medium\n and a.db_level <= high\n then\n log(\n "old >= new + margin, new >= medium and old <= high"\n )\n log(\n "Old source is significantly louder than new one."\n )\n log(\n "Transition: crossed, fade-in."\n )\n add(a.source, fade_in(b.source))\n elsif\n # Do not fade if it\'s already very low.\n b.db_level >= a.db_level + margin\n and a.db_level <= medium\n and b.db_level <= high\n then\n log(\n "new >= old + margin, old <= medium and new <= high."\n )\n log(\n "Do not fade if it\'s already very low."\n )\n log(\n "Transition: crossed, no fade."\n )\n add(a.source, b.source)\n\n # What to do with a loud end and a quiet beginning?\n # A good idea is to use a jingle to separate the two tracks,\n # but that\'s another story.\n else\n # Otherwise, A and B are just too loud to overlap nicely, or the\n # difference between them is too large and overlapping would completely\n # mask one of them.\n log(\n "No transition: using default."\n )\n default(a.source, b.source)\n end\n end\n\n cross(width=width, duration=start_next, transition, s)\nend\n\n# Create a radiopilote-driven source\ndef channel_radiopilote(~skip=true, name) =\n log(\n "Creating canal #{name}"\n )\n\n # Request function\n def req() =\n log(\n "Request for #{name}"\n )\n ret =\n list.hd(\n process.read.lines(\n scripts ^\n "radiopilote-getnext " ^\n process.quote(name) ^\n sed\n )\n )\n log(\n "Got answer: #{ret} for #{name}"\n )\n request.create(ret)\n end\n\n # Create the dynamic source.\n s = request.dynamic(id="dyn_" ^ name, req, timeout=60.)\n\n # Apply normalization using replaygain information.\n s = amplify(1., override="replay_gain", s)\n\n # Skip blank when asked to\n s = if skip then blank.skip(s, max_blank=10., threshold=-40.) else s end\n\n # Submit new tracks on lastfm\n s.on_metadata(synchronous=false, lastfm)\n\n # Tell the system when a new track is played\n s.on_metadata(\n synchronous=false,\n fun (meta) ->\n process.run(\n scripts ^\n "radiopilote-feedback " ^\n process.quote(meta["canal"]) ^\n " " ^\n process.quote(meta["file_id"]) ^\n "\'"\n )\n )\n\n # Finally apply a smart crossfading\n crossfade(s)\nend\n\n# Basic source\njazz = channel_radiopilote("jazz")\ndiscoqueen = channel_radiopilote("discoqueen")\n\n# Avoid skipping blank with classic music !!\nclassique = channel_radiopilote(skip=false, "classique")\nThat70Sound = channel_radiopilote("That70Sound")\nmetal = channel_radiopilote("metal")\nreggae = channel_radiopilote("reggae")\nRock = channel_radiopilote("Rock")\n\n# Group those sources in a separate\n# clock (good for multithreading/multicore)\nclock.assign_new([jazz, That70Sound, metal, reggae])\n\n# === Mixing live ===\n\n# To create a channel from a basic source, add:\n# - a new-track notification for radiopilote\n# - metadata rewriting\n# - the live shows\n# - the failsafe \'interlude\' source to channels\n# - blank detection\ndef mklive(s) =\n # Fade in when selecting live or returning from it. NOTE: We cannot skip the\n # current song because reloading new songs for all the sources when live\n # starts costs too much CPU.\n live =\n live.{\n on_select =\n fun ({starting, ..._}) ->\n begin\n log(\n "Transition to live!"\n )\n fade.in(starting)\n end\n }\n s =\n (s : source).{\n on_select =\n fun ({starting, ..._}) ->\n begin\n log(\n "Transitioning from live!"\n )\n fade.in(starting)\n end\n }\n fallback([live, s, interlude])\nend\n\n# Create a channel using mklive(), encode and output it to icecast.\ndef mkoutput(~out=out, mount, source, name, genre) =\n out(id=(mount : string), mount=mount, name=name, genre=genre, mklive(source))\nend\n\n# === Outputs ===\n\nmkoutput(\n "jazz",\n jazz,\n "RadioPi - Canal Jazz",\n "jazz"\n)\nmkoutput(\n "discoqueen",\n discoqueen,\n "RadioPi - Canal DiscoQueen",\n "discoqueen"\n)\nmkoutput(\n "classique",\n classique,\n "RadioPi - Canal Classique",\n "classique"\n)\nmkoutput(\n "That70Sound",\n That70Sound,\n "RadioPi - Canal That70Sound",\n "That70Sound"\n)\nmkoutput(\n "metal",\n metal,\n "RadioPi - Canal Metal",\n "metal"\n)\nmkoutput(\n "reggae",\n reggae,\n "RadioPi - Canal Reggae",\n "reggae"\n)\nmkoutput(\n "Rock",\n Rock,\n "RadioPi - Canal Rock",\n "Rock"\n)\n\n# Test outouts\nmkoutput(\n out=out_aac,\n "reggae.aacp",\n reggae,\n "RadioPi - Canal Reggae (64 kbits AAC+ test stream)",\n "reggae"\n)\nmkoutput(\n out=out_aac32,\n "reggae.aacp32",\n reggae,\n "RadioPi - Canal Reggae (32 kbits AAC+ test stream)",\n "reggae"\n)\n'})}),"\n",(0,i.jsx)(e.p,{children:"The other machine has a similar configuration except that files are local, but this is exactly the same for liquidsoap !"}),"\n",(0,i.jsxs)(e.p,{children:["Using harbor, the live connects directly to liquidsoap, using port ",(0,i.jsx)(e.code,{children:"8000"})," (icecast runs on port ",(0,i.jsx)(e.code,{children:"8080"}),").\nThen, liquidsoap starts a relay to the other encoder, and both switch their channels to the new live."]}),"\n",(0,i.jsx)(e.p,{children:"Additionally, a file output is started upon live connection, in order to backup the stream. You could also add a relay to\nicecast in order to manually check what's received by the harbor."})]})}function c(n={}){let{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,i.jsx)(e,{...n,children:(0,i.jsx)(u,{...n})}):u(n)}},28453(n,e,a){a.d(e,{R:()=>s,x:()=>r});var t=a(96540);let i={},o=t.createContext(i);function s(n){let e=t.useContext(o);return t.useMemo(function(){return"function"==typeof n?n(e):{...e,...n}},[e,n])}function r(n){let e;return e=n.disableParentContext?"function"==typeof n.components?n.components(i):n.components||i:s(n.components),t.createElement(o.Provider,{value:e},n.children)}}}]);